/* Product framing: one complete demonstration and two exploratory investigations. */
const FUTURES={
 incident:{title:'Did the campaign fail, or did payment fail?',label:'Payment friction across systems',pain:'“Sales dropped. Should I change the campaign, give a discount, or help customers retry?”',sources:['Campaign cohorts','Payment health','Orders & inventory','Consent history'],signal:'Paid conversion fell during a short incident',steps:['Join the campaign cohort to payment attempts','Check payment health against inventory and order status','Find the eligible unpaid audience'],evidence:[['Campaign cohort','1,000 matched visitors; 84 shoppers encountered the affected payment route.','Needed: campaign-to-order identifiers'],['Payment health','The error spike coincides with the drop; the route has recovered in this sample.','Needed: provider incident and method health'],['Orders and inventory','32 shoppers later paid. For the 52 still unpaid, sample stock is available and order value is unchanged.','Needed: current order and inventory read'],['Consent ledger','38 of the 52 unpaid shoppers have the required recorded contact consent.','Needed: consent, opt-outs and contact history']],hypotheses:[['Weak campaign message','Unresolved','We have no experiment showing a copy problem.'],['Payment incident','Supported association','Timing and affected-method concentration fit; this is not proof of every shopper’s intent.'],['Unavailable stock','Less supported','Current stock is available; historical availability still needs verification.']],question:'What should the agent prepare after payment health recovers?',choices:[['retry','A single reminder for eligible shoppers','Recheck payment, stock and consent before any send.'],['hold','An internal recovery brief','Keep customer contact off until the team reviews.']],recommendation:'Prepare one retry reminder without a new discount. Exclude later-paid orders and opt-outs, recheck current health and stock, then request approval for exact content and a capped audience.',alternative:'Prepare a merchant-only brief with the affected cohort and unresolved evidence. No customer contact is authorised.',metric:'Incremental contribution per eligible assigned shopper, after contact costs and refunds.',learning:'A 38-person cohort is too small for a reliable standalone lift estimate. Use it to validate safe execution; plan a sufficiently powered evaluation before claiming revenue lift.',why:'AI synthesises incident notes, campaign context and competing explanations. Fixed checks decide payment status, stock, consent and permitted actions.',limits:'No Meta or Google Ads connection is assumed. Cross-system attribution, health feeds and inventory permissions must be validated.'},
 economics:{title:'The campaign sells more. Is it earning more?',label:'Contribution across systems',pain:'“The campaign report looks great, but rewards and returns may be eating the gain.”',sources:['Campaign assignments','Reward funding','Cost ledger','Orders & refunds'],signal:'Redemptions rise while retained contribution falls',steps:['Reconcile campaign orders with reward funding','Include variable costs and mature refunds','Compare interventions within the merchant’s margin floor'],evidence:[['Campaign assignments','More redemptions are observed, but no randomised comparison exists yet.','Needed: assigned customer and campaign IDs'],['Reward funding','The current ₹150 reward is merchant-funded; bank support is not assumed.','Needed: funding contract and redemption ledger'],['Cost ledger','Verified sample costs leave ₹500 per retained order before reward; ₹350 after today’s reward.','Needed: COGS, fulfilment and payment costs'],['Orders and refunds','Some recent orders remain inside the return window; early revenue is not mature contribution.','Needed: return status, refund costs and retained orders']],hypotheses:[['Reward is too generous','Worth testing','A smaller reward saves cost, but could reduce conversion.'],['Return-heavy product mix','Unresolved','Wait for mature cohorts and compare product mix before attributing the drop.'],['Funding misclassification','Check first','Confirm merchant versus bank liability before proposing a new reward.']],question:'Which business constraint should shape the investigation?',choices:[['margin','Protect ₹400 per retained order','Assess a separate ₹75 reward with verified costs.'],['mature','Wait for the return window to mature','Draft an analysis plan before changing incentives.']],recommendation:'Propose a separately approved ₹75 reward variant against the existing ₹150 reward. The sample retained-order contribution would be ₹425, but conversion and return rates may change. Preserve issued rewards and set a worst-case redemption budget.',alternative:'Hold the reward change. Prepare a cohort reconciliation task and re-evaluate once refunds and funding are verified. The agent should be allowed to recommend no intervention.',metric:'Incremental contribution per assigned customer, including returns, merchant funding and intervention costs.',learning:'Use random assignment and mature outcomes to compare the smaller reward with current practice. Learn which intervention works; do not treat high purchase propensity as evidence of incremental impact.',why:'AI reconciles funding explanations, interprets cost context and proposes a bounded experiment. A calculation service enforces contribution floors and maximum exposure.',limits:'Razorpay payments alone do not reveal product costs, funding liability or all return costs. Missing costs block a profit claim.'}
};
const futureState={};let futureId='incident',futureTimer=null;
const oldOverview=overview,oldSidebar=sidebar,oldCaseView=caseView,oldEvidence=evidence,oldRender=render,oldModal=modal;
CASES.clarity.intro='Ananya, 180 shoppers encountered offer eligibility rejections in Festive Edit; 54 later paid. I can compare the campaign wording, offer rules and payment evidence before proposing a test. Shall I investigate?';
CASES.clarity.story='Ananya runs Sunday Home. Her campaign headline promises ₹500 cashback, while the eligible card, minimum order and payout timing appear later. Some shoppers encounter offer rejections. The task is to investigate whether earlier disclosure helps profitable conversion.';
CASES.clarity.evidence[1]=['Unique shoppers trying offer','600'];
CASES.clarity.signal='180 shoppers with offer rejections';
sidebar=function(){return oldSidebar().replace('<span class="count">4</span>','').replace('<div class="navlabel">ENGAGE</div>',`<button class="nav ${page==='future'?'active':''}" onclick="openFuture('incident')">${icon('chart')}<span>Future opportunities</span></button><div class="navlabel">ENGAGE</div>`)};
overview=function(){return `<div class="crumb">Workspace / Engage / Campaign decisions</div>${heading('Campaign outcome studio','A proposed extension to Razorpay Engage',btn('Start focused demo '+icon('arrow'),"openCase('clarity')",'primary'))}<section class="hero"><div><div class="eyebrow">The ambition</div><h2>Find what is weakening a campaign.<br>Act to improve profitable conversion.</h2><p>Bring campaign, offer and payment evidence together. Investigate likely causes, approve a targeted intervention and learn from measured outcomes.</p><div class="row">${pill('One focus area, end to end','green')}${pill('Two future investigations','blue')}</div></div><div class="heroart"><div class="orb">${icon('spark')}</div></div></section><div class="scope-strip"><div><div class="eyebrow">Existing foundation</div><h3>Engage already runs campaigns</h3><p>Offers, transaction-led targeting, campaign optimisation and retention tools are publicly described.</p><a class="strategy-link" href="https://razorpay.com/engage/" target="_blank" rel="noopener">Read about Engage ↗</a></div><div><div class="eyebrow">Our proposed extension</div><h3>Investigate, decide and measure</h3><p>We propose a joined investigation, a merchant-approved intervention and a controlled contribution comparison.</p><button class="strategy-link" onclick="modal('difference')">What is actually new?</button></div><div><div class="eyebrow">What this prototype proves</div><h3>A reviewable merchant journey</h3><p>One focused case runs from signal to sample outcome. Future cases explore wider evidence. All execution is simulated.</p></div></div><div class="section-intro"><h2>Start here · One focus area, end to end</h2><p>Offer-related campaign friction. Clarity is the intervention we test, not a proven cause of abandonment.</p></div><section class="panel focus-card"><div>${pill('FOCUSED DEMONSTRATION','green')}<h2>Shoppers try the offer.<br>Some never complete payment.</h2><p>Festive Edit has 180 shoppers with eligibility rejections. Compare the campaign promise, configured terms and later payments. Approve a small clarity test only after reviewing the evidence.</p><div class="source-chips"><span>Campaign wording</span><span>Offer configuration</span><span>Checkout events</span><span>Payments & refunds</span></div>${btn('Walk through the full journey '+icon('arrow'),"openCase('clarity')",'primary')}</div><div class="focus-flow">${['Detect and investigate the opportunity','Review evidence and answer one question','Edit, preview and approve the intervention','Watch agents execute within limits','Measure contribution and decide what comes next'].map((x,i)=>`<div><b>${i+1}</b>${x}</div>`).join('')}</div></section><div class="section-intro"><h2>Where the same decision agent could go next</h2><p>Two future cases show why several evidence sources matter. These are exploration flows, not additional MVP commitments.</p></div><div class="future-grid">${Object.entries(FUTURES).map(([id,c])=>`<section class="panel future-card">${pill('FUTURE OPPORTUNITY','purple')}<h3>${c.title}</h3><p>${c.pain}</p><div class="source-chips">${c.sources.map(s=>`<span>${s}</span>`).join('')}</div>${btn('Explore the investigation '+icon('arrow'),`openFuture('${id}')`)}<small class="fine">Proposed connections · Fictional evidence</small></section>`).join('')}</div><details class="panel other-examples"><summary>Earlier scenario explorations</summary><p class="spaced">Retained for comparison. The recommended presentation starts with the focused journey above, then shows the two future investigations.</p><div class="row">${['recovery','cost','repeat'].map(id=>btn(CASES[id].short,`openCase('${id}')`)).join('')}</div></details>`};
caseView=function(){return (current==='clarity'?`<div class="focus-banner"><strong>Focused demonstration:</strong> offer-related campaign friction → approved clarity test → measured contribution.<button onclick="goHome()">See the bigger picture</button></div>`:'')+oldCaseView()};
function sourceBoard(rows){return `<div class="evidence-board">${rows.map(([name,detail,state])=>`<div class="evidence-source"><span class="source-state">${state}</span><strong>${name}</strong><p>${detail}</p></div>`).join('')}</div>`}
evidence=function(){return (current==='clarity'?`<section class="panel" style="margin-bottom:24px"><div class="eyebrow">A hypothesis built from several sources</div><h2>What supports the intervention—and what does not</h2>${sourceBoard([['Campaign version','The headline promises ₹500 cashback. The card condition appears in the footer.','Sample content record'],['Configured offer','Cedar credit cards, ₹2,500 minimum and a 90-day bank payout. Terms must remain unchanged.','Sample offer record'],['Checkout events','180 of 600 unique shoppers trying the offer encounter eligibility rejection. Instrumentation is required.','Sample event record'],['Payment outcomes','54 of those 180 later pay; 126 have no matched payment in 24 hours. Intent remains unknown.','Sample payment join']])}<div class="hypothesis-row"><strong>Terms may be discovered too late</strong><span>Worth testing: copy and terms differ in prominence. This does not establish why shoppers left.</span></div><div class="hypothesis-row"><strong>Payment outage or low purchase intent</strong><span>Not ruled out. No incident feed or customer-intent evidence is supplied in this focused case.</span></div><p class="spaced">Recommend a reversible communication test; do not label all 126 shoppers as recoverable revenue. A controlled comparison must establish benefit.</p></section>`:'')+oldEvidence()};
function openFuture(id){futureId=id;page='future';futureState[id] ||= {stage:'intro',step:0,choice:null,paused:false};render();window.scrollTo(0,0)}
function futureView(){let c=FUTURES[futureId],s=futureState[futureId];return `<div class="future-work"><div class="crumb"><button onclick="goHome()">Overview</button> / Future opportunities</div>${heading(c.title,c.label,`<button class="btn" onclick="goHome()">${icon('back')} Bigger picture</button>`)}<div class="future-notice"><strong>Future concept.</strong> This illustrates a possible investigation using additional sources. Connections and write permissions are unverified. No real data is read and no action is executed.</div><section class="panel chatpanel"><div class="chatbar"><div class="row"><div class="agentmini">${icon('spark')}</div><h3>Your campaign assistant</h3></div>${pill('Exploration mode','purple')}</div><div class="chatscroll">${message({role:'bot',text:c.pain+' I need to compare several sources before recommending what you should change.'})}<div class="source-chips">${c.sources.map(x=>`<span>${x}</span>`).join('')}</div>${s.stage==='intro'?`<p>${c.signal}. A single report cannot tell us which intervention will help.</p>${btn('Investigate across sources '+icon('arrow'),'runFuture()','primary spaced')}`:s.stage==='running'?`<div class="inline-run"><div class="between"><h3>Comparing evidence</h3><span>${Math.round(s.step/3*100)}%</span></div><div class="progressbar"><div class="progressfill" style="width:${s.step/3*100}%"></div></div>${c.steps.map((x,i)=>`<div class="future-step ${i<s.step?'complete':i===s.step?'active':''}"><span>${i<s.step?'✓':i+1}</span><strong>${x}</strong></div>`).join('')}<div class="row spaced">${btn(s.paused?'Resume':'Pause','pauseFuture()')}${btn('Stop','stopFuture()')}</div></div>`:`${s.stage==='stopped'?'<div class="future-notice">Investigation stopped. No actions were taken.</div>'+btn('Restart investigation','runFuture()'):futureFindings(c,s)}`}</div></section><button class="strategy-link" onclick="openCase('clarity')">Return to the complete focused demonstration →</button></div>`}
function futureFindings(c,s){return `${sourceBoard(c.evidence)}<h3>Compare explanations before choosing an action</h3>${c.hypotheses.map(([title,state,why])=>`<div class="hypothesis-row"><div><strong>${title}</strong><small>${state}</small></div><span>${why}</span></div>`).join('')}<div class="questionbox"><div class="eyebrow">Merchant decision</div><h3>${c.question}</h3><div class="choices">${c.choices.map(([id,title,detail])=>`<button class="choice" onclick="futureChoose('${id}')" aria-pressed="${s.choice===id}"><strong>${s.choice===id?'✓ ':''}${title}</strong><small>${detail}</small></button>`).join('')}</div></div>${s.choice?`<div class="future-result"><div class="eyebrow">Proposed next step · Draft only</div><h3>${s.choice===c.choices[0][0]?'Prepare a bounded intervention':'Hold execution and resolve uncertainty'}</h3><p>${s.choice===c.choices[0][0]?c.recommendation:c.alternative}</p><div class="comparebox spaced"><strong>Before any execution</strong><p>Review the source evidence, exact audience, content, funding and limits. Approve a versioned plan. Pause or stop future work. A missing permission or uncertain write blocks execution.</p></div><h3 class="spaced">Measure and learn</h3><p>${c.metric} ${c.learning}</p><h3 class="spaced">Why AI helps</h3><p>${c.why}</p><p class="fine spaced">${c.limits}</p>${btn('Save as an exploration brief','saveFutureBrief()','primary spaced')}${s.saved?'<p role="status" class="spaced">✓ Exploration brief saved for this session. No campaign change or customer contact.</p>':''}</div>`:''}`}
function runFuture(){clearInterval(futureTimer);Object.assign(futureState[futureId],{stage:'running',step:0,paused:false,choice:null,saved:false});render();futureTimer=setInterval(()=>{for(const [id,s] of Object.entries(futureState)){if(s.stage!=='running'||s.paused)continue;s.step++;if(s.step>=3)s.stage='findings';if(page==='future'&&futureId===id)render()}if(!Object.values(futureState).some(s=>s.stage==='running'))clearInterval(futureTimer)},1400)}
function pauseFuture(){futureState[futureId].paused=!futureState[futureId].paused;render()}
function stopFuture(){futureState[futureId].stage='stopped';render()}
function futureChoose(choice){futureState[futureId].choice=choice;futureState[futureId].saved=false;let y=window.scrollY;render();window.scrollTo(0,y)}
function saveFutureBrief(){futureState[futureId].saved=true;let y=window.scrollY;render();window.scrollTo(0,y)}
render=function(){if(page!=='future'){oldRender();return}$('sidebar').innerHTML=sidebar();$('main').innerHTML=futureView();$('journey').innerHTML='';history.replaceState(null,'','#future/'+futureId)};
modal=function(type){if(type!=='difference'&&type!=='guide'){oldModal(type);return}let title=type==='difference'?'Existing capabilities and our proposed extension':'One complete journey, then the ambition';let body=type==='difference'?`<p>Engage already describes offer rules, transaction-led targeting, campaign optimisation and retention journeys. Agent Studio describes recovery agents and merchant controls.</p><p>Our proposed extension investigates a campaign using joined evidence, compares plausible explanations, selects a bounded intervention and measures incremental contribution against a control.</p><p>We have not verified this exact workflow in public documentation. That is an unverified gap, not proof Razorpay lacks it internally. The full integration and merchant demand need validation.</p><a class="strategy-link" href="https://razorpay.com/engage/" target="_blank" rel="noopener">Engage capabilities ↗</a><a class="strategy-link" href="https://razorpay.com/blog/razorpay-agent-studio-principles-guardrails-and-merchant-control/" target="_blank" rel="noopener">Agent Studio capabilities and controls ↗</a>`:`<p>Start with the focused offer-friction case. Investigate in chat, inspect Evidence & journey, answer who controls the page, edit and preview the copy, approve the test, then review the sample outcome.</p><p>Return to Overview for two future investigations: payment incident recovery and contribution after rewards and returns. Each compares four evidence sources and asks a different merchant question. These illustrate ambition, not additional MVP promises.</p><p>All data and actions are simulated. Earlier examples remain available under Earlier scenario explorations. Reloading resets the session.</p>`;let dlg=document.createElement('dialog');dlg.className='personal-modal';dlg.setAttribute('aria-label',title);dlg.innerHTML=`<div class="between"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div>${body}<div class="actions">${btn('Done','closeModal()')}</div>`;$('overlay').replaceChildren(dlg);dlg.showModal()};
const baseReset=resetDemo;resetDemo=function(){clearInterval(futureTimer);for(const id of Object.keys(futureState))delete futureState[id];baseReset()};
render();
const baseResultTab=resultTab;
resultTab=function(){if(current!=='clarity'||!A().results)return baseResultTab();return `<div class="callout">${icon('info')}Constructed outcome example · Not a forecast or a live result. The fixed comparison below uses 500 visitors per group; it does not recalculate when you edit the demo cap.</div><div class="metrics">${metric('Contribution / assigned visitor','₹90 → ₹99','Point estimate: +₹9 after defined costs')}${metric('Paid conversion','30% → 33%','150 vs 165 paid orders')}${metric('Additional discount','₹0','Financial offer unchanged')}${metric('Rollout decision','Do not scale yet','Uncertainty and refund maturity unresolved')}</div><div class="grid"><section class="panel"><h2>Did the intervention improve profitable conversion?</h2><p class="spaced">Compare all assigned visitors, including those who did not click or pay. Conversion alone cannot establish a profit benefit.</p><table class="table sectionspace"><thead><tr><th>Illustrative measure</th><th>Control</th><th>Clearer terms</th></tr></thead><tbody><tr><td>Assigned visitors</td><td>500</td><td>500</td></tr><tr><td>Paid orders</td><td>150</td><td>165</td></tr><tr><td>Net contribution after defined costs</td><td>₹45,000</td><td>₹49,500</td></tr><tr><td>Contribution per assigned visitor</td><td>₹90</td><td>₹99</td></tr></tbody></table><p class="fine spaced">Contribution accounts for refunds, product and variable fulfilment costs, payment fees, merchant-funded incentives and intervention cost. Avoid counting a discount twice.</p><div class="comparebox sectionspace"><h3>The next decision needs stronger evidence</h3><p>The point estimate is encouraging, but these counts do not establish reliable lift. Check uncertainty, assignment balance and mature refunds against a predeclared sample plan. Any wider audience needs another merchant approval.</p></div><div class="row spaced">${btn('Review or revise the plan','revise()','primary')}${btn('Stop future exposure','stopWork();switchTab(\'chat\')')}</div></section><aside class="panel"><h3>What the agent learns</h3><p class="spaced">Save source versions, the hypothesis, merchant edits, assigned groups, costs and mature outcomes. A negative result should reduce confidence in recommending this intervention again.</p><h3 class="spaced">What stays uncertain</h3><p class="spaced">Whether the offer caused the original abandonment; whether the measured difference is reliable; and whether the result transfers to another campaign.</p><p class="spaced">Learning stays scoped to this merchant. No cross-merchant model training is required.</p></aside></div>`};
